const _raw = $input.first().json;
const payload = (_raw && _raw.data) ? _raw.data : _raw;
const state = Array.isArray(payload) ? payload[0] : payload;
const A = state.assertions || [];

const add = (m, k, v, ev) => {
  if (!k) return;
  if (!m[k]) m[k] = { key: k, weighted: 0, count: 0, evidence_ids: [] };
  m[k].weighted += v;
  m[k].count += 1;
  if (ev && m[k].evidence_ids.length < 12 && !m[k].evidence_ids.includes(ev)) m[k].evidence_ids.push(ev);
};

const worldSupply = {}, genreSupply = {}, genreDemand = {}, buyerDemand = {}, engineSupply = {};
const formatSupply = {}, formatDemand = {}, audienceByGenre = {}, buyerFormat = {}, buyerGenre = {};
const routeByType = {}, economics = [], formatTrends = [], legalFlaggedWorlds = {};

for (const a of A) {
  const w = a.weight;
  switch (a.assertion_type) {
    case 'supply':
      add(worldSupply, a.world, w, a.evidence_id);
      for (const e of (a.engines || [])) add(engineSupply, e, w, a.evidence_id);
      break;
    case 'genre_supply':
      add(genreSupply, a.genre, w * (a.title_count || 1), a.evidence_id);
      if (a.format) add(formatSupply, a.format, w, a.evidence_id);
      break;
    case 'buyer_demand':
      add(buyerDemand, a.buyer, w * Math.max(0, a.direction_value), a.evidence_id);
      for (const g of (a.genres || [])) {
        add(genreDemand, g, w * Math.max(0, a.direction_value), a.evidence_id);
        add(buyerGenre, a.buyer + '|' + g, w, a.evidence_id);
      }
      if (a.format) {
        add(formatDemand, a.format, w * Math.max(0, a.direction_value), a.evidence_id);
        add(buyerFormat, a.buyer + '|' + a.format, w, a.evidence_id);
      }
      break;
    case 'audience_demand':
      for (const g of (a.genres || [])) add(audienceByGenre, g, w * Math.max(0, a.direction_value), a.evidence_id);
      break;
    case 'genre_demand':
      for (const g of (a.genres || [])) add(genreDemand, g, w * a.direction_value, a.evidence_id);
      break;
    case 'saturation':
      for (const g of (a.genres || [])) add(genreSupply, g, w * 1.5, a.evidence_id);
      break;
    case 'economics':
      economics.push({ evidence_id: a.evidence_id, metric: a.metric_name, value: a.metric_value, dir: a.direction_value, weight: w, interpretation: a.interpretation });
      break;
    case 'route':
      add(routeByType, a.route_type, w * a.direction_value, a.evidence_id);
      break;
    case 'format_trend':
      formatTrends.push({ evidence_id: a.evidence_id, metric: a.metric_name, value: a.metric_value, dir: a.direction_value, weight: w, interpretation: a.interpretation, buyers: a.buyers });
      add(formatDemand, 'vertical_microdrama', w * Math.max(0, a.direction_value), a.evidence_id);
      break;
    case 'legal_flag':
      for (const w2 of (a.worlds || [])) legalFlaggedWorlds[w2] = (legalFlaggedWorlds[w2] || 0) + 1;
      break;
  }
}

// Normalise a map to 0..1 on its weighted value
const normalise = (m) => {
  const vals = Object.values(m).map(x => x.weighted);
  const max = Math.max(1e-9, ...vals.map(Math.abs));
  const out = {};
  for (const k of Object.keys(m)) out[k] = Object.assign({}, m[k], { index: m[k].weighted / max });
  return out;
};

const rank = (m) => Object.values(m).sort((a, b) => b.weighted - a.weighted).map(x => ({ key: x.key, weighted: Number(x.weighted.toFixed(3)), count: x.count, evidence_ids: x.evidence_ids }));

// Economics posture: is the market pushing toward cheap/contained production?
let costPressure = 0, costWeight = 0;
for (const e of economics) { costPressure += (e.dir < 0 ? 1 : 0) * e.weight; costWeight += e.weight; }
const cost_pressure_index = costWeight > 0 ? costPressure / costWeight : 0;

return [{ json: {
  stage: 'WF-12',
  generated_at: new Date().toISOString(),
  source_stage: state.stage,
  assertion_count: A.length,
  cost_pressure_index: Number(cost_pressure_index.toFixed(3)),
  economics_signal_count: economics.length,
  format_trend_signal_count: formatTrends.length,
  clusters: {
    world_supply: normalise(worldSupply),
    engine_supply: normalise(engineSupply),
    genre_supply: normalise(genreSupply),
    genre_demand: normalise(genreDemand),
    audience_by_genre: normalise(audienceByGenre),
    buyer_demand: normalise(buyerDemand),
    format_supply: normalise(formatSupply),
    format_demand: normalise(formatDemand),
    buyer_genre: normalise(buyerGenre),
    buyer_format: normalise(buyerFormat),
    route_by_type: normalise(routeByType)
  },
  legal_flagged_worlds: legalFlaggedWorlds,
  economics_signals: economics,
  format_trend_signals: formatTrends,
  rankings: {
    top_worlds_by_supply: rank(worldSupply).slice(0, 20),
    top_genres_by_supply: rank(genreSupply).slice(0, 15),
    top_genres_by_demand: rank(genreDemand).slice(0, 15),
    top_buyers_by_demand: rank(buyerDemand).slice(0, 15),
    formats_by_demand: rank(formatDemand),
    routes: rank(routeByType)
  }
} }];
